import{_ as t,o as a,c as d,ag as s}from"./chunks/framework.DMVuHR7L.js";const p=JSON.parse('{"title":"Test-sync rules (for agents)","description":"","frontmatter":{},"headers":[],"relativePath":"bots/test-sync.md","filePath":"bots/test-sync.md","lastUpdated":1780343633000}'),o={name:"bots/test-sync.md"};function r(i,e,n,c,l,h){return a(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="test-sync-rules-for-agents" tabindex="-1">Test-sync rules (for agents) <a class="header-anchor" href="#test-sync-rules-for-agents" aria-label="Permalink to &quot;Test-sync rules (for agents)&quot;">​</a></h1><blockquote><p><strong>The rule.</strong> Core flows are exercised by tests, and the tests stay in sync with the behaviour they cover. New behaviour ships with new tests; existing tests get updated when the behaviour underneath them moves.</p></blockquote><h2 id="two-test-layers" tabindex="-1">Two test layers <a class="header-anchor" href="#two-test-layers" aria-label="Permalink to &quot;Two test layers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Runner</th><th>Lives in</th><th>What it covers</th></tr></thead><tbody><tr><td>Unit</td><td>Vitest (<code>npm test</code>)</td><td><code>src/**/*.{test,spec}.{ts,tsx}</code></td><td>Pure logic — parsers, snap math, layout transforms, filter parsing, etc. No DOM, fixtures inline.</td></tr><tr><td>End-to-end</td><td>Playwright (<code>npm run e2e</code>)</td><td><code>tests/*.spec.ts</code></td><td>Behaviour in a real browser, driven against the <a href="./../features/simulator">simulator</a>. Empty state, connect, every widget&#39;s happy path, dashboard chrome (drag, resize, eye toggle, undo, etc.).</td></tr></tbody></table><p>The real WebUSB transport is <strong>not</strong> in CI — there are no devices. That path is exercised manually against the deployed staging URL before promoting to production.</p><h2 id="coverage-contract-—-the-canonical-core-flows" tabindex="-1">Coverage contract — the canonical core flows <a class="header-anchor" href="#coverage-contract-—-the-canonical-core-flows" aria-label="Permalink to &quot;Coverage contract — the canonical core flows&quot;">​</a></h2><p>These flows must always have green e2e coverage. If you change the behaviour, update the matching test in the same PR. If you remove the behaviour, remove the test.</p><table tabindex="0"><thead><tr><th>Flow</th><th>Test fixture (current)</th></tr></thead><tbody><tr><td>Empty state renders the connect / fake-data CTA</td><td><code>empty state &gt; renders the connect-or-fake-data card</code></td></tr><tr><td>Clicking <em>fake data</em> swaps to the dashboard and starts streaming</td><td><code>simulator &gt; clicking &quot;fake data&quot; swaps in the dashboard …</code></td></tr><tr><td>Filter bar autocomplete shows the five starter types</td><td><code>filter bar &gt; focusing the empty input shows …</code></td></tr><tr><td>Filter chip commits and persists</td><td><code>filter bar &gt; typing a filter produces a chip</code></td></tr><tr><td><code>?</code> opens the help dialog</td><td><code>keyboard shortcuts &gt; ? opens the help dialog</code></td></tr><tr><td>Palette has all five widget cards enabled</td><td><code>dashboard &gt; + Add widget opens the palette …</code></td></tr><tr><td>Dumpsys runs a preset against the simulator</td><td><code>dashboard &gt; Dumpsys tile runs a preset …</code></td></tr><tr><td>Files renders the toolbar + sdcard tree</td><td><code>dashboard &gt; adding a Files widget …</code></td></tr><tr><td>Logcat tiles keep filters per-tile</td><td><code>dashboard &gt; adding a Logcat widget yields …</code></td></tr><tr><td>Mirror renders + is capped at 1 instance</td><td><code>dashboard &gt; Mirror tile renders the simulated app frame …</code></td></tr><tr><td>Shell runs simulator commands</td><td><code>dashboard &gt; adding a Shell widget runs the simulator commands</code></td></tr><tr><td>Drag-to-swap rearranges tiles</td><td><code>dashboard &gt; dragging a tile by the grip onto another tile swaps them</code></td></tr><tr><td>Drag-the-seam resizes tiles</td><td><code>dashboard &gt; dragging the seam between two tiles resizes them</code></td></tr><tr><td>Eye toggle cycles bar mode</td><td><code>dashboard &gt; the eye toggle cycles bar mode</code></td></tr><tr><td>Maximize / restore</td><td><code>dashboard &gt; maximize fills the viewport; restore returns to grid</code></td></tr><tr><td>Clear layout empties the dashboard</td><td><code>dashboard &gt; Clear layout empties the dashboard …</code></td></tr><tr><td>Cmd+Z / Cmd+Shift+Z undo / redo widget addition</td><td><code>dashboard &gt; Cmd+Z undoes a widget addition …</code></td></tr><tr><td>Per-widget settings cog opens a modal for each kind</td><td><code>dashboard &gt; cog opens a per-widget settings modal …</code> (one test per kind)</td></tr><tr><td>Wrap toggle stays in sync between modal and on-bar control</td><td><code>dashboard &gt; Logcat modal &quot;Wrap&quot; toggle and on-bar wrap button …</code></td></tr><tr><td>Palette dismiss paths (Esc / scrim / × button)</td><td><code>dashboard &gt; the +Add palette closes via Esc, scrim click, and the close button</code></td></tr><tr><td>Global settings cog opens the dialog with both controls</td><td><code>dashboard &gt; global settings cog opens the dialog …</code></td></tr></tbody></table><p>When the flow&#39;s UI selectors move, <em>update the existing test</em> — don&#39;t add a parallel one. The fixture name is the contract; renaming it breaks GitHub&#39;s flaky-test history.</p><h2 id="adding-a-new-widget" tabindex="-1">Adding a new widget <a class="header-anchor" href="#adding-a-new-widget" aria-label="Permalink to &quot;Adding a new widget&quot;">​</a></h2><p>A new widget kind requires, at minimum, e2e coverage for:</p><ol><li>The palette card is <strong>enabled</strong> when the widget kind is the only one of its kind, or up to its <code>maxInstances</code> cap.</li><li>Adding the widget from the palette spawns exactly one tile of that kind.</li><li>The widget&#39;s canonical happy-path interaction works against the simulator (Shell runs <code>pwd</code>; Dumpsys returns parsed cards; Files resolves a breadcrumb; Mirror renders the bezel + frame placeholder; Logcat shows streamed entries).</li><li>The cog opens a per-widget settings modal.</li><li>If the widget caps at one instance, the palette card disables after the cap is hit.</li></ol><p>Mirror these patterns from the existing <code>tests/smoke.spec.ts</code> rather than inventing a new style.</p><h2 id="selector-idioms" tabindex="-1">Selector idioms <a class="header-anchor" href="#selector-idioms" aria-label="Permalink to &quot;Selector idioms&quot;">​</a></h2><ul><li>Filter <code>.tile</code> by widget class (<code>.lc-widget</code>, <code>.sh-widget</code>, …) instead of <code>.tile.nth(N)</code>. The dwindle layout doesn&#39;t pin tiles to fixed DOM positions and <code>nth(N)</code> is brittle.</li><li>For pointer-driven interactions that race with hover state (tooltip pseudo-elements, just-toggled suppression, head-hidden reveal strips), prefer <code>await el.evaluate((n) =&gt; (n as HTMLButtonElement).click())</code> over <code>await el.click()</code>. The DOM-level click skips Playwright&#39;s actionability checks and fires React&#39;s <code>onClick</code> deterministically.</li><li>Use the <code>.beforeEach</code> already in <code>tests/smoke.spec.ts</code> to seed <code>localStorage</code> with <code>performanceMode: &#39;on&#39;</code> — it disables tile position transitions so bbox probes after drags / resizes see the final layout, not a frame mid-easing.</li></ul><h2 id="adding-new-pure-logic" tabindex="-1">Adding new pure logic <a class="header-anchor" href="#adding-new-pure-logic" aria-label="Permalink to &quot;Adding new pure logic&quot;">​</a></h2><p>Anything in <code>src/lib/</code> that doesn&#39;t touch the DOM gets a Vitest unit test. The <code>lib/filters.test.ts</code> (when it exists) is the style to mirror — fixtures inline, no helpers spread across files. Keep tests side by side with the code:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/lib/foo.ts</span></span>
<span class="line"><span>src/lib/foo.test.ts</span></span></code></pre></div><p>The Vitest config picks up <code>src/**/*.{test,spec}.{ts,tsx}</code> — no extra registration needed.</p><h2 id="when-tests-fail" tabindex="-1">When tests fail <a class="header-anchor" href="#when-tests-fail" aria-label="Permalink to &quot;When tests fail&quot;">​</a></h2><ul><li><strong>Don&#39;t <code>--no-verify</code> past a failing hook.</strong> Fix the underlying issue.</li><li><strong>Don&#39;t disable the failing test to land the PR.</strong> If a test is genuinely flaky (and you&#39;ve verified it locally), surface it; don&#39;t just skip it.</li><li>The Playwright trace lands in <code>playwright-report/</code> on failure (CI uploads it as an artefact). Read the trace before guessing.</li></ul>`,21)])])}const u=t(o,[["render",r]]);export{p as __pageData,u as default};
